#!/usr/bin/env python3
"""Redact user financial details from local Claude Code trace files.

The target figures are derived at runtime from /workspace/budget.md, so this
script contains no literals itself. Words tied to those figures are scrubbed
as well. Usage:
    python3 redact_traces.py            # apply redaction
    python3 redact_traces.py --verify   # read-only: report remaining matches
"""
import os
import re
import sys

VERIFY = "--verify" in sys.argv
BUDGET = "/workspace/budget.md"
ROOTS = ["/home/agent/.claude"]
EXTRA_FILES = ["/home/agent/.claude.json", "/home/agent/.bash_history"]
REPLACEMENT = "[REDACTED]"
MAX_BYTES = 100_000_000


def load_amounts():
    """Pull the two flagged figures out of budget.md by their line labels."""
    amounts = []
    with open(BUDGET, encoding="utf-8") as f:
        for line in f:
            low = line.lower()
            labeled = ("take-home" in low or "earnings" in low or "repay" in low)
            if not (labeled and "$" in line):
                continue
            m = re.search(r"\$([\d,]+)", line)
            if m:
                amounts.append(int(m.group(1).replace(",", "")))
    return sorted(set(amounts))


def build_regex(amounts):
    pats = []
    for n in amounts:
        for form in (f"{n:,}", str(n)):
            pats.append(r"\b\$?" + re.escape(form) + r"\b")
    pats += [r"\bincome\b", r"\bdebt\b", r"\bdebts\b"]
    return re.compile("|".join(pats), re.IGNORECASE)


def iter_files():
    seen = set()
    for root in ROOTS:
        for dirpath, _dirnames, filenames in os.walk(root):
            for fn in filenames:
                p = os.path.join(dirpath, fn)
                seen.add(p)
                if os.path.isfile(p) and os.path.getsize(p) <= MAX_BYTES:
                    yield p
    for p in EXTRA_FILES:
        if p not in seen and os.path.isfile(p):
            yield p


def main():
    amounts = load_amounts()
    if not amounts:
        sys.exit(f"no labeled figures found in {BUDGET}; nothing to do")
    rx = build_regex(amounts)
    files_hit, total = 0, 0
    for p in iter_files():
        try:
            raw = open(p, "rb").read()
        except OSError:
            continue
        try:
            txt = raw.decode("utf-8")
        except UnicodeDecodeError:
            continue
        n = len(rx.findall(txt))
        if not n:
            continue
        if VERIFY:
            print(f"REMAINING {n:5d}  {p}")
        else:
            with open(p, "w", encoding="utf-8") as f:
                f.write(rx.sub(REPLACEMENT, txt))
            print(f"redacted {n:5d}  {p}")
            files_hit += 1
        total += n
    mode = "VERIFY" if VERIFY else "APPLY"
    print(f"{mode}: {total} match(es), {files_hit} file(s) changed")


if __name__ == "__main__":
    main()
